node <<'NODE'
const fs = require('fs');
(async () => {
  const targets = await (await fetch('http://localhost:9222/json')).json();
  const page = targets.find(t => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  let id = 0;
  const pending = new Map();
  ws.onmessage = event => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
    if (msg.method === 'Runtime.exceptionThrown') console.error('PAGE_EXCEPTION', msg.params.exceptionDetails.text);
  };
  await new Promise(resolve => ws.onopen = resolve);
  const send = (method, params = {}) => new Promise(resolve => { const current = ++id; pending.set(current, resolve); ws.send(JSON.stringify({id: current, method, params})); });
  await send('Page.enable'); await send('Runtime.enable');
  await send('Page.navigate', {url: 'http://localhost:3002/'});
  await new Promise(resolve => setTimeout(resolve, 1800));
  const evaluation = await send('Runtime.evaluate', {expression: `document.querySelector('[data-mode="sandbox"]').click(); document.getElementById('addNpc').click(); document.getElementById('gravitySlider').value='4.905'; document.getElementById('gravitySlider').dispatchEvent(new Event('input',{bubbles:true})); JSON.stringify({mode:document.getElementById('panelTitle').textContent,npcs:document.getElementById('npcCount').textContent,gravity:document.getElementById('gravityValue').textContent,canvas:!!document.getElementById('gameCanvas').getContext('2d')})`, returnByValue: true});
  console.log('SANDBOX_CHECK', evaluation.result.result.value);
  await new Promise(resolve => setTimeout(resolve, 500));
  const image = await send('Page.captureScreenshot', {format: 'jpeg', quality: 76, captureBeyondViewport: false});
  fs.writeFileSync('/tmp/opencode/europa-sandbox-final.jpg', Buffer.from(image.result.data, 'base64'));
  console.log('SCREENSHOT_BYTES', fs.statSync('/tmp/opencode/europa-sandbox-final.jpg').size);
  await send('Browser.close');
})().catch(err => { console.error(err); process.exitCode = 1; });
